#!/usr/bin/env python3
"""Inspect the executable containers generated by the Switch build."""
import argparse
import hashlib
import json
import os
import pathlib
import platform
import re
import shutil
import struct
import subprocess


def verify_nro(path):
    data = path.read_bytes()
    if len(data) < 0x80 or data[0x10:0x14] != b'NRO0':
        raise ValueError(f'{path} is not an NRO')
    payload_size = struct.unpack_from('<I', data, 0x18)[0]
    if not 0x80 <= payload_size <= len(data):
        raise ValueError(f'Invalid NRO payload size in {path}')
    if path.suffix == '.nro' and data[payload_size:payload_size + 4] != b'ASET':
        raise ValueError(f'Expected NRO asset header in {path}')
    return hashlib.sha256(data).hexdigest()


def read_app_metadata(data):
    asset = struct.unpack_from('<I', data, 0x18)[0]
    if data[asset:asset + 4] != b'ASET' or asset + 0x38 > len(data):
        raise ValueError('Missing NRO asset header')
    offset, size = struct.unpack_from('<QQ', data, asset + 0x18)
    if offset < 0x38 or size != 0x4000 or asset + offset + size > len(data):
        raise ValueError('Invalid embedded NACP bounds')
    nacp = data[asset + offset:asset + offset + size]
    return {
        'title': nacp[:0x200].split(b'\0', 1)[0].decode('utf-8'),
        'author': nacp[0x200:0x300].split(b'\0', 1)[0].decode('utf-8'),
        'version': nacp[0x3060:0x3070].split(b'\0', 1)[0].decode('utf-8'),
    }


def inspect_elf(path, expected_symbol=None, expected_version=None):
    """Read Switch ELF section metadata without requiring a host readelf."""
    data = path.read_bytes()
    if len(data) < 64 or data[:7] != b'\x7fELF\x02\x01\x01' or struct.unpack_from('<H', data, 0x12)[0] != 183:
        raise ValueError(f'{path} is not a little-endian AArch64 ELF64')
    table = struct.unpack_from('<Q', data, 0x28)[0]
    entry_size, count, names = struct.unpack_from('<HHH', data, 0x3A)
    if table < 64 or entry_size != 64 or names >= count or table + entry_size * count > len(data):
        raise ValueError(f'Invalid ELF section table in {path}')
    sections = [struct.unpack_from('<IIQQQQIIQQ', data, table + i * entry_size) for i in range(count)]

    def contents(section):
        offset, size = section[4:6]
        if offset + size > len(data):
            raise ValueError(f'Invalid ELF section bounds in {path}')
        return data[offset:offset + size]

    def c_string(strings, offset):
        return strings[offset:strings.index(0, offset)]

    section_names = contents(sections[names])
    by_name = {c_string(section_names, entry[0]): entry for entry in sections}
    note = contents(by_name[b'.note.gnu.build-id'])
    if len(note) < 16 or note[:4] != b'\x04\0\0\0' or note[8:16] != b'\x03\0\0\0GNU\0':
        raise ValueError(f'Invalid GNU build-ID note in {path}')
    id_size = struct.unpack_from('<I', note, 4)[0]
    if not 0 < id_size <= 32 or 16 + id_size > len(note):
        raise ValueError(f'Invalid GNU build-ID length in {path}')

    if expected_symbol is not None:
        symbol_table = by_name[b'.symtab']
        strings = contents(sections[symbol_table[6]])
        symbols = struct.iter_unpack('<IBBHQQ', contents(symbol_table))
        if not any(index != 0 and (info & 0xF) == 2 and expected_symbol in c_string(strings, name)
                   for name, info, _, index, _, _ in symbols):
            raise ValueError(f'Missing linked {expected_symbol.decode()} function in {path}')
    if expected_version is not None and expected_version.encode('ascii') + b'\0' not in contents(by_name[b'.rodata']):
        raise ValueError(f'Sysmodule ELF is missing build version {expected_version!r} in .rodata')

    return note[16:16 + id_size], by_name[b'.bss'][5]


def verify_build_id(container, build_id, path):
    if container[0x40:0x60] != build_id.ljust(32, b'\0'):
        raise ValueError(f'{path} does not match the linked ELF build ID')


def verify_exefs(path):
    data = path.read_bytes()
    if len(data) < 16 or data[:4] != b'PFS0':
        raise ValueError(f'{path} is not PFS0')
    count, names_size = struct.unpack_from('<II', data, 4)
    names_at = 16 + 24 * count
    payload_at = names_at + names_size
    if payload_at > len(data):
        raise ValueError(f'Invalid PFS0 header sizes in {path}')
    entries = {}
    for i in range(count):
        offset, size, name_offset, _ = struct.unpack_from('<QQII', data, 16 + i * 24)
        name_at = names_at + name_offset
        if not names_at <= name_at < payload_at or payload_at + offset + size > len(data):
            raise ValueError(f'Invalid PFS0 entry in {path}')
        end = data.index(0, name_at, payload_at)
        name = data[name_at:end].decode('ascii')
        if name in entries:
            raise ValueError(f'Duplicate PFS0 entry {name} in {path}')
        entries[name] = data[payload_at + offset:payload_at + offset + size]
    if not entries.get('main', b'').startswith(b'NSO0') or not entries.get('main.npdm', b'').startswith(b'META'):
        raise ValueError(f'Expected NSO executable and NPDM metadata in {path}')
    return hashlib.sha256(data).hexdigest(), entries


def describe_artifact(source, path, digest):
    return {'path': path.relative_to(source).as_posix(), 'bytes': path.stat().st_size, 'sha256': digest}


def native_sources(source, elf_paths):
    source_files = {source / 'UPSTREAM.json', source / 'console/Makefile'}
    for name, elf in elf_paths:
        module = elf.parent
        files = [module / 'Makefile', *sorted((source / 'common').glob('*.h'))]
        files.extend(path for path in (module / 'source').rglob('*') if path.is_file())
        if name == 'app':
            files.append(module / 'icon.jpg')
            files.extend(source / name for name in (
                'app/data/game_catalog.bin', 'scripts/compile-title-catalog.py',
                'compatibility/title-catalog/catalog.json', 'compatibility/title-catalog/lcid-mappings.json'))
        else:
            files.extend(path for path in (module / 'res').rglob('*') if path.is_file())
        for path in files:
            if path.stat().st_mtime_ns > elf.stat().st_mtime_ns:
                raise ValueError(f'{path} is newer than {elf}, rebuild before reporting evidence')
        source_files.update(files)
    hashes = {path.relative_to(source).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
              for path in sorted(source_files)}
    digest = hashlib.sha256(json.dumps(hashes, sort_keys=True, separators=(',', ':')).encode('utf-8')).hexdigest()
    return {'sha256': digest, 'files_sha256': hashes}


def toolchain_details(provenance):
    if devkita64 := os.environ.get('DEVKITA64'):
        compiler = pathlib.Path(devkita64) / 'bin/aarch64-none-elf-gcc'
    elif devkitpro := os.environ.get('DEVKITPRO'):
        compiler = pathlib.Path(devkitpro) / 'devkitA64/bin/aarch64-none-elf-gcc'
    else:
        compiler = shutil.which('aarch64-none-elf-gcc')
    if compiler is None:
        raise ValueError('Set DEVKITA64, DEVKITPRO or PATH to the compiler used for the build report')
    banner = subprocess.check_output([compiler, '--version'], text=True).splitlines()[0]
    return {'declared_dependencies': provenance['toolchain'], 'compiler_version': banner}


def verify_ipc_abi(source, expected):
    app = (source / 'app/source/lobby_model.h').read_text(encoding='utf-8')
    app_main = (source / 'app/source/main.c').read_text(encoding='utf-8')
    console = source / 'console/ldn_mitm/source'
    relay = (console / 'lanywhere_relay.hpp').read_text(encoding='utf-8')
    service = (console / 'lanywhere_service.hpp').read_text(encoding='utf-8')
    implementation = (console / 'lanywhere_service.cpp').read_text(encoding='utf-8')

    def number(contents, expression, description):
        match = re.search(expression, contents, re.MULTILINE)
        if match is None:
            raise ValueError(f'Missing declared {description} in native source')
        return int(match.group(1), 0)

    app_major = number(app, r'^#define LANYWHERE_IPC_MAJOR\s+(\d+)\b', 'app IPC major')
    module_major = number(relay, r'^\s*constexpr u32 ProtocolVersion\s*=\s*(\d+)\b', 'sysmodule IPC major')
    app_command = number(app, r'^#define LANYWHERE_IPC_CAPABILITIES_COMMAND\s+(\d+)\b', 'app capability command')
    module_command = number(service,
                            r'AMS_SF_METHOD_INFO\(C, H,\s*(\d+),\s*Result,\s*GetProtocolCapabilities,\s*\(ams::sf::Out<u32> out\)',
                            'sysmodule capability command with u32 reply')
    if app_major != expected or module_major != expected or app_command != 10 or module_command != app_command:
        raise ValueError('App and sysmodule capability declarations disagree with the expected IPC ABI')
    if not re.search(r'serviceDispatchOut\(\s*&g_lanywhere,\s*LANYWHERE_IPC_CAPABILITIES_COMMAND\b', app_main):
        raise ValueError('App does not dispatch the declared capability command')
    if not re.search(r'GetProtocolCapabilities\([^{}]*\)\s*\{[^{}]*\bSetValue\((?:lanywhere::)?ProtocolVersion\)', implementation):
        raise ValueError('Sysmodule capability handler does not return the declared major')

    sizes = {}
    for app_name, module_name, expected_size in ([('LobbyGroup', 'GroupSummaryV2', 336), ('LobbyPage', 'GroupPageV2', 16), ('LobbyMatch', 'MatchStatus', 88)] if expected >= 5 else [('LobbyGroup', 'GroupSummary', 64), ('LobbyPage', 'GroupPage', 8), ('LobbyMatch', 'MatchStatus', 88)]):
        expression = r'^\s*(?:_Static_assert|static_assert)\(sizeof\({}\)\s*==\s*(0x[0-9a-fA-F]+|\d+)\b'
        app_size = number(app, expression.format(app_name), app_name + ' size assertion')
        module_size = number(relay, expression.format(module_name), module_name + ' size assertion')
        if app_size != expected_size or module_size != expected_size:
            raise ValueError(f'App and sysmodule layout assertions disagree for {module_name}')
        sizes[module_name] = expected_size

    match_offsets = {'room': 16, 'error': 24}
    for field, offset in match_offsets.items():
        for contents, name in [(app, 'LobbyMatch'), (relay, 'MatchStatus')]:
            pattern = rf'offsetof\({name},\s*{field}\)\s*==\s*(\d+)\b'
            if number(contents, pattern, f'{name}.{field} offset') != offset:
                raise ValueError(f'App and sysmodule MatchStatus field offset differs for {field}')

    return {'major': expected, 'capability_command': app_command, 'capability_reply': 'u32',
            'declared_layout_sizes_bytes': sizes, 'match_status_offsets_bytes': match_offsets}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('source', type=pathlib.Path)
    parser.add_argument('--app-title', help='expected NRO display title')
    parser.add_argument('--app-version', help='expected NRO display version')
    parser.add_argument('--overlay-title', default='LANywhere', help='expected Tesla overlay display title')
    parser.add_argument('--require-capabilities', action='store_true',
                        help='require the linked sysmodule capability IPC function')
    parser.add_argument('--ipc-abi', type=int, help='expected app/sysmodule IPC capability major')
    parser.add_argument('--report', type=pathlib.Path, help='write verification evidence as JSON')
    parser.add_argument('--build-command', action='append', default=[],
                        help='record the actual build command, repeat for each command')
    args = parser.parse_args()
    if args.report is not None and not args.build_command:
        parser.error('--report requires at least one --build-command used for these artifacts')
    source = args.source
    console = source / 'console/out/sd'
    app = source / 'app/lanywhere.nro'
    app_hash = verify_nro(app)
    print(app_hash, app, f'({app.stat().st_size} bytes)')
    config = console / 'switch/ldnmitm_config/ldnmitm_config.nro'
    print(verify_nro(config), config, f'({config.stat().st_size} bytes)')
    overlay = console / 'switch/.overlays/lanywhere.ovl'
    overlay_hash = verify_nro(overlay)
    overlay_data = overlay.read_bytes()
    overlay_leaf = source / 'console/overlay/overlay.ovl'
    overlay_elf = overlay_leaf.with_suffix('.elf')
    if overlay_data != overlay_leaf.read_bytes():
        raise ValueError('Packaged Tesla overlay differs from the leaf artifact')
    overlay_id, overlay_bss = inspect_elf(overlay_elf)
    verify_build_id(overlay_data, overlay_id, overlay)
    overlay_metadata = read_app_metadata(overlay_data)
    if overlay_metadata['title'] != args.overlay_title:
        raise ValueError(f'Tesla overlay title is {overlay_metadata["title"]!r}, expected {args.overlay_title!r}')
    print(overlay_hash, overlay, f'({overlay.stat().st_size} bytes)')
    print(f'  Tesla overlay {overlay_metadata["title"]} / {overlay_metadata["version"]}')
    app_data = app.read_bytes()
    app_metadata = read_app_metadata(app_data)
    for field, expected in [('title', args.app_title), ('version', args.app_version)]:
        if expected is not None and app_metadata[field] != expected:
            raise ValueError(f'NRO {field} is {app_metadata[field]!r}, expected {expected!r}')
    app_elf = app.with_suffix('.elf')
    app_id, app_bss = inspect_elf(app_elf)
    verify_build_id(app_data, app_id, app)
    print(f"  NACP {app_metadata['title']} / {app_metadata['author']} / {app_metadata['version']}")
    print(f'  AArch64 ELF build ID {app_id.hex()}, .bss {app_bss} bytes')
    exefs = console / 'atmosphere/contents/4200000000000010/exefs.nsp'
    digest, entries = verify_exefs(exefs)
    print(digest, exefs, f'({exefs.stat().st_size} bytes)')
    for name, data in entries.items():
        print(f'  {name}: {len(data)} bytes')
    flag = exefs.parent / 'flags/boot2.flag'
    if not flag.is_file() or flag.stat().st_size != 0:
        raise ValueError('Missing or nonempty Atmosphère boot flag')
    module = source / 'console/ldn_mitm/ldn_mitm.elf'
    provenance = json.loads((source / 'UPSTREAM.json').read_text())
    version = provenance['derived_version']
    if overlay_metadata['version'] != version:
        raise ValueError('Tesla overlay NACP version differs from the release version')
    capabilities = None
    if args.require_capabilities or args.ipc_abi is not None:
        capabilities = b'LanywhereService23GetProtocolCapabilities'
    module_id, module_bss = inspect_elf(module, capabilities, version)
    verify_build_id(entries['main'], module_id, exefs)
    for name, suffix in [('main', '.nso'), ('main.npdm', '.npdm')]:
        if entries[name] != module.with_suffix(suffix).read_bytes():
            raise ValueError(f'SD build ExeFS {name} differs from the leaf artifact')
    print(f'  Sysmodule {version}, AArch64 ELF build ID {module_id.hex()}, .bss {module_bss} bytes')
    ipc = verify_ipc_abi(source, args.ipc_abi) if args.ipc_abi is not None else None
    if ipc is not None:
        ipc['capability_handler_linked'] = True
        print(f"  Paired native source declares IPC ABI {ipc['major']}, command {ipc['capability_command']}, linked sysmodule handler present")
    if args.report is not None:
        app_report = describe_artifact(source, app, app_hash)
        app_report.update({'format': 'NRO0 with ASET', 'nacp': app_metadata,
                           'elf_build_id': app_id.hex(), 'static_bss_bytes': app_bss})
        overlay_report = describe_artifact(source, overlay, overlay_hash)
        overlay_report.update({'format': 'Tesla NRO0 with ASET', 'nacp': overlay_metadata,
                               'elf_build_id': overlay_id.hex(), 'static_bss_bytes': overlay_bss})
        module_report = describe_artifact(source, exefs, digest)
        module_report.update({'format': 'PFS0 ExeFS', 'embedded_version': version,
                              'elf_build_id': module_id.hex(), 'static_bss_bytes': module_bss,
                              'boot2_flag': flag.relative_to(source).as_posix(),
                              'entries': {name: {'bytes': len(data), 'magic': data[:4].decode('ascii'),
                                                 'sha256': hashlib.sha256(data).hexdigest()}
                                          for name, data in sorted(entries.items())}})
        report = {'mode': 'host cross-compilation and binary inspection',
                  'host': {'system': platform.system(), 'architecture': platform.machine()},
                  'target': 'Nintendo Switch AArch64 ELF64', 'hardware_tested': False,
                  'build_commands': args.build_command, 'source_revisions': provenance,
                  'toolchain': toolchain_details(provenance),
                  'native_sources': native_sources(source, [('app', app_elf), ('sysmodule', module), ('overlay', overlay_elf)]),
                  'ipc_abi': ipc, 'ipc_capability_function_linked': True if capabilities is not None else None,
                  'artifacts': [app_report, module_report, overlay_report]}
        args.report.parent.mkdir(parents=True, exist_ok=True)
        args.report.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')


if __name__ == '__main__':
    main()
